package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;
public record LoginAttempt(String attemptId,String normalizedUsername,String subjectId,String tenantId,boolean successful,String reasonCode,String ipAddress,String userAgent,String correlationId,Instant attemptedAt){public LoginAttempt{attemptId=Text.required(attemptId,"attemptId",128);normalizedUsername=Text.required(normalizedUsername,"normalizedUsername",128);subjectId=Text.optional(subjectId,128);tenantId=Text.optional(tenantId,64);reasonCode=Text.required(reasonCode,"reasonCode",128);ipAddress=Text.optional(ipAddress,128);userAgent=Text.optional(userAgent,1000);correlationId=Text.required(correlationId,"correlationId",128);Objects.requireNonNull(attemptedAt,"attemptedAt");}}
